from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, replacing scalar missing values by ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length with binary-search comparisons performed in C."""
        high = min(len(left), len(right))
        low = 0
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact fixed-string Trie reuse using sorted adjacent LCPs."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        return sum(
            cls._lcp(left, right)
            for left, right in zip(ordered, ordered[1:])
        )

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each row using its row-specific column permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells, mode: int) -> List[int]:
        """Rank columns by repeated serialized values and their character lengths."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            total_length = 0

            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            repetition = sum(
                count * (count - 1)
                for count in counts.values()
            )
            weighted = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )

            if mode == 0:
                key = weighted
            else:
                key = repetition * max(
                    1, total_length // max(1, n)
                )

            ranked.append((key, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _boundary_affinity(self, cells, rows, columns):
        """Measure repeated last-character to first-character transitions."""
        size = len(columns)
        affinity = [[0] * size for _ in range(size)]

        suffix_counts = []
        prefix_counts = []

        for column in columns:
            suffix = {}
            prefix = {}

            for row in rows:
                value = cells[row, column]
                first = value[:1]
                last = value[-1:]

                prefix[first] = prefix.get(first, 0) + 1
                suffix[last] = suffix.get(last, 0) + 1

            prefix_counts.append(prefix)
            suffix_counts.append(suffix)

        for left in range(size):
            for right in range(size):
                if left == right:
                    continue

                score = 0
                for character, left_count in suffix_counts[left].items():
                    score += (
                        left_count *
                        prefix_counts[right].get(character, 0)
                    )
                affinity[left][right] = score

        return affinity

    def _refine_leaf(self, cells, rows, order) -> List[int]:
        """Construct an affinity-guided path over ten columns plus one insertion pass."""
        if len(order) < 2 or len(rows) < 2:
            return list(order)

        active = list(order[:10])
        tail = list(order[10:])
        size = len(active)

        if size < 2:
            return list(order)

        affinity = self._boundary_affinity(cells, rows, active)

        # Start from the frequency-ranked first column and greedily follow
        # the strongest repeated character continuation.
        path = [0]
        unused = set(range(1, size))

        while unused:
            previous = path[-1]
            next_index = max(
                unused,
                key=lambda index: (
                    affinity[previous][index],
                    -index,
                ),
            )
            path.append(next_index)
            unused.remove(next_index)

        path = [active[index] for index in path]
        position_of = {column: index for index, column in enumerate(active)}

        # One deterministic insertion pass repairs weak internal boundaries.
        for position in range(1, len(path)):
            item = path[position]
            item_index = position_of[item]
            best_position = position
            best_gain = 0

            for destination in range(position):
                right_index = position_of[path[destination]]

                if destination == 0:
                    old_score = 0
                    new_score = affinity[item_index][right_index]
                else:
                    left_index = position_of[path[destination - 1]]
                    old_score = affinity[left_index][right_index]
                    new_score = (
                        affinity[left_index][item_index] +
                        affinity[item_index][right_index]
                    )

                gain = new_score - old_score
                if gain > best_gain:
                    best_gain = gain
                    best_position = destination

            if best_position < position:
                path.pop(position)
                path.insert(best_position, item)

        return path + tail

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Choose one repeated leading field and affinity-optimize each suffix group."""
        n, m = cells.shape

        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead_scores = []

        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            lead_scores.append((score, column))

        lead = max(
            lead_scores,
            key=lambda item: (item[0], -item[1])
        )[1]

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(m) if column != lead]
        result = [None] * n

        for rows in groups.values():
            ranked = []

            for column in remaining:
                counts = {}
                for row in rows:
                    value = cells[row, column]
                    counts[value] = counts.get(value, 0) + 1

                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((score, column))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            suffix = self._refine_leaf(
                cells,
                rows,
                [column for _, column in ranked],
            )
            full_order = [lead] + suffix

            for row in rows:
                result[row] = full_order[:]

        return result

    def _candidate(self, cells, orders):
        """Serialize, score, and lexicographically sort one complete candidate."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row),
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global and one conditional affinity candidate losslessly."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        conditional = self._conditional_orders(cells)

        candidates = [
            [global_a[:] for _ in range(n)],
            [global_b[:] for _ in range(n)],
            conditional,
        ]

        best = None

        for orders in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature))

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, strings, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column]
                for column in source_order
            ]
            column_orders.append([
                df.columns[column]
                for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

